from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions
from azure.core.credentials import AzureKeyCredential
from.safety_client import get_client


def redact_unsafe(payload, config=None):
    client = get_client(config)
    response = client.analyze_text(AnalyzeTextOptions(text=payload['text'], output_type='EightSeverityLevels'))
    redacted_text = payload['text']
    for category in response.categories_analysis:
        if category.severity > 3:
            redacted_text = redacted_text.replace(category.text, '[REDACTED]')
    return {'redacted_text': redacted_text}

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential


def get_client(config):
    return ContentSafetyClient(config['endpoint'], AzureKeyCredential(config['api_key']))

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {'text': payload.get('text', '')}


def parse_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {'toxicity': max((category.get('severity', 0) for category in response.get('categories_analysis', [])), default=0) / 7}

from.safety_client import get_client
from.safety_models import parse_response


def moderation_summary(payloads, config=None):
    client = get_client(config)
    results = []
    for payload in payloads:
        response = client.analyze_text(payload)
        results.append(parse_response(response))
    return {'summary': results}

from google.cloud import translate_v2 as translate


def appeal_translate(payload, config=None):
    client = translate.Client(config['api_key'])
    result = client.translate(payload['text'], target_language='en')
    return {'translated_text': result['translatedText']}

from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential


def moderation_reason_embedding(payload, config=None):
    client = TextAnalyticsClient(endpoint=config['endpoint'], credential=AzureKeyCredential(config['api_key']))
    result = client.extract_key_phrases(documents=[payload['text']])
    return {'embedding': result[0].key_phrases}
